/* Isolated travel examples reachable from Update Test Field; never assign the real player state. */
(function(){'use strict';const W=DecideWorldTravel,el=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x));let sample=null;const dialog=document.createElement('dialog');dialog.id='worldTravelTest';dialog.innerHTML='<h2>ทดสอบแผนที่และการเดินทาง</h2><p>ตัวละครและแผนที่จำลอง ไม่เปลี่ยนเซฟ ฐานข้อมูล หรือรางวัลจริง</p><label>สถานการณ์<select id="worldTestPreset"><option value="walk">เดินเท้า 80 กม.</option><option value="cart">รถม้า 80 กม.</option><option value="story">อีเวนต์สนทนาใน ROAD-TEST</option><option value="combat">อีเวนต์ต่อสู้บน grid ใน ROAD-TEST</option><option value="novel">VN: สุ่มหลายอีเวนต์ / ไอเท็ม / เควส / บทหลังสู้</option></select></label><button id="worldTestReset">เริ่มตัวอย่างใหม่</button><div id="worldTestBody"></div><p id="worldTestStatus" role="status"></p><button id="worldTestClose">ปิด</button>';document.body.append(dialog);const button=document.createElement('button');button.id='worldTravelTestOpen';button.textContent='ทดสอบแผนที่ / เดินทาง';el('labBack').after(button);
function build(){const mode=el('worldTestPreset').value,c=EvervaleMapData.defaults(),event={id:'EVT-TEST',name:mode==='combat'?'โจรริมทาง':'คาราวานริมทาง',kind:mode==='combat'?'combat':'story',text:'ตัวอย่างอีเวนต์ที่เกิดเฉพาะ ROAD-TEST',routeIds:['ROAD-TEST'],weight:1,once:true,enabled:true,choices:[{id:'greet',label:'ทักทาย รับข่าวสาร',text:'คุยกับคาราวาน',goldDelta:5,energyDelta:0,minutes:15}],monsterId:'preset-monster-goblin',enemyCount:1,allowRetreat:true,minutes:0};c.routes=[{id:'ROAD-TEST',name:'ถนนตัวอย่าง',from:{mapId:'world',placeId:'rest'},to:{mapId:'world',placeId:'work'},km:['walk','cart'].includes(mode)?80:10,terrain:'road',eventChance:['story','combat'].includes(mode)?100:0,enabled:true}];c.events=['story','combat'].includes(mode)?[event]:[];if(mode==='novel'){c.routes[0].km=10;const npc=R.records(DB).find(r=>r.kind==='npc'&&r.enabled!==false),item=R.records(DB).find(r=>r.kind==='item'&&r.enabled!==false);c.events=[{...event,id:'VN-TEST',kind:'story',routeChances:[{routeId:'ROAD-TEST',chance:100}],novel:{npcId:npc?.id||'',startNode:'start',background:'',nodes:[{id:'start',text:'ช่วยนำเสบียงไปส่งได้ไหม? รับไอเท็มกับเควสจำลอง แล้วเจอโจรบน grid',choices:[{id:'accept',label:'รับเสบียงและเข้าสู้',items:item?[{kind:'item',id:item.id,quantity:1}]:[],quest:{id:'quest-demo',title:'ส่งเสบียงจำลอง',description:'ผ่านโจรและนำเสบียงถึงปลายทาง',status:'active'},combat:{monsterId:'preset-monster-goblin',enemyCount:1,winNode:'win',lossNode:'loss',retreatNode:'loss'}}]},{id:'win',text:'ผ่านโจรแล้ว ขอบคุณที่ช่วยส่งเสบียง',choices:[{id:'done',label:'ส่งงานสำเร็จ',quest:{id:'quest-demo',title:'ส่งเสบียงจำลอง',description:'ส่งเสบียงสำเร็จ',status:'completed'}}]},{id:'loss',text:'การเดินทางยังดำเนินต่อได้',choices:[{id:'leave',label:'เดินทางต่อ'}]}]}},{...event,id:'SECOND-TEST',kind:'story',text:'อีเวนต์ที่สองสุ่มแยก 100% จึงเกิดต่อจากเหตุการณ์แรก',routeChances:[{routeId:'ROAD-TEST',chance:100}]},{...event,id:'ZERO-TEST',kind:'story',routeChances:[{routeId:'ROAD-TEST',chance:0}]}];}const config=EvervaleMapData.validate(c),s=EvervaleRules.fresh(),N=DecideCreation;EvervaleRules.createCharacter(s,'ผู้เดินทางจำลอง','human','mage',{},N.recommend({...N.draft(),job:'mage',weapon:'staff'}));s.learned=EvervaleRules.records(DB).filter(r=>DecideCatalogActions.compile(r)).map(r=>r.key);sample={config,state:W.begin(s,config,'ROAD-TEST',mode==='cart'?'cart':'walk',()=>.1)};draw();}
function mutate(fn){try{sample.state=fn();el('worldTestStatus').textContent='';draw();}catch(e){el('worldTestStatus').textContent=e.message;}}
function action(root,id,label,fn){const button=document.createElement('button');button.id=id;button.textContent=label;button.onclick=fn;root.append(button);}
function draw(){const root=el('worldTestBody');root.replaceChildren();if(!sample)return;const s=sample.state,j=s.overworld.journey,info=document.createElement('p');info.textContent='วัน '+s.days+' เวลา '+Math.floor(s.minute/60)+':'+String(s.minute%60).padStart(2,'0')+' • เหรียญจำลอง '+s.gold+(j?' • '+j.progressKm+'/'+j.route.km+' กม.':' • ถึงจุดหมายแล้ว');root.append(info);const plan=W.estimate(sample.config.routes[0],el('worldTestPreset').value==='cart'?'cart':'walk',sample.config.travelSettings),p=document.createElement('p');p.textContent='เคลื่อนที่ '+DecideWorldTravelUI.fmt(plan.movingMinutes)+' / รวมพัก '+DecideWorldTravelUI.fmt(plan.elapsedMinutes);root.append(p);if(!j)return;const pending=j.pendingEvent,e=W.activeEvent(pending);if(e){const text=document.createElement('p');text.textContent=e.name+' • '+e.text+' • คิวอีก '+(j.eventQueue?.length||0)+' เหตุการณ์';root.append(text);DecideEventNovelUI.journal(root,s);if(e.kind==='story'&&e.novel)DecideEventNovelUI.render(root,s,pending,R.records(DB),id=>mutate(()=>W.resolve(s,id,R.records(DB))),{prefix:'worldTestChoice-'});else if(e.kind==='story')for(const ch of e.choices)action(root,'worldTestChoice',ch.label,()=>mutate(()=>W.resolve(s,ch.id,R.records(DB))));else if(!s.expedition)action(root,'worldTestFight','เข้าสู้ในสนามทดสอบ grid จริง',()=>mutate(()=>{const next=DecideWorldTravelCombat.begin(s,R.records(DB),DB.overrides);DecideCatalogActions.prepare(next.expedition,next,R.records(DB));DecideMonsterAI.prepare(next.expedition,R.records(DB));DecideMonsterPassives.prepare(next.expedition,R.records(DB));sample.state=next;dialog.close();DecideCombatLab.openExternal(next.expedition);return next;}));else action(root,'worldTestRecoverResult','รับผลสนามจำลอง',()=>mutate(()=>{const fight=DecideCombatLab.snapshot().session?.e;if(!fight?.travelEvent||fight.travelEvent.journeyId!==j.id)throw Error('สนามถูกเปลี่ยนแล้ว เริ่มตัวอย่างใหม่');if(fight.status==='active')throw Error('การต่อสู้ยังไม่จบ');return DecideCombatRules.settle({...s,expedition:fight}).snapshot;}));}else action(root,'worldTestAdvance','เดินทางต่อหนึ่งช่วง',()=>mutate(()=>W.advance(s)));}
button.onclick=()=>{if(!sample)build();else draw();dialog.showModal();};el('worldTestReset').onclick=build;el('worldTestPreset').onchange=()=>{};el('worldTestClose').onclick=()=>dialog.close();window.DecideWorldTravelSandbox={snapshot:()=>copy(sample)};
})();
